document.querySelector('#playBtn').onclick=openMainMenu;document.querySelector('#exitBtn').onclick=()=>showToast('Você pode fechar esta aba para sair.');document.querySelector('#adventureBtn').onclick=openAdventure;document.querySelector('#settingsBtn').onclick=openSettings;document.querySelector('#attackBtn').onclick=attackNearestMonster;const interactBtn=document.querySelector('#interactBtn');if(interactBtn)interactBtn.onclick=interactNearby;
const directionKeys={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};
function syncDirection(d){if(keyHeld.has(d)||Array.from(pointerDirs.values()).includes(d))held.add(d);else held.delete(d)}
function releasePointer(e){const d=pointerDirs.get(e.pointerId);if(d){pointerDirs.delete(e.pointerId);syncDirection(d)}}
document.querySelectorAll('[data-dir]').forEach(b=>{const d=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();pointerDirs.set(e.pointerId,d);held.add(d);try{b.setPointerCapture(e.pointerId)}catch(_){}},{passive:false});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,releasePointer));b.addEventListener('contextmenu',e=>e.preventDefault())});
window.addEventListener('pointerup',releasePointer);window.addEventListener('pointercancel',releasePointer);
window.addEventListener('keydown',e=>{const d=directionKeys[e.key];if(d){keyHeld.add(d);held.add(d);e.preventDefault()}if(e.key.toLowerCase()==='e'&&screen==='game')showToast('Você observa a região ao redor.');if(e.key==='Escape'){document.querySelectorAll('.modal').forEach(n=>n.remove());modalHistory=[]}});
window.addEventListener('keyup',e=>{const d=directionKeys[e.key];if(d){keyHeld.delete(d);syncDirection(d)}});
function clearMovement(){pointerDirs.clear();keyHeld.clear();held.clear()}
window.addEventListener('blur',clearMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearMovement()});
// Slimes vivos do campo de caça. XP só é concedida quando um monstro é derrotado.
const slimeBaseSpawns=[[2370,880],[2470,890],[2540,945]];
// Coordenadas diretas do mundo: a vila termina perto de X=1880 e o campo começa em X=2000.
function interactNearby(){if(screen!=='game')return;const targets=[{id:'mayor',x:1568,y:835,label:'Prefeito Aldren'},{id:'quest',x:2280,y:900,label:'Lia, responsável pelas caçadas'},{id:'guild',x:1396,y:822,label:'Guilda dos Aventureiros'},{id:'smith',x:1501,y:819,label:'Ferreiro'},{id:'inn',x:1684,y:821,label:'Hospedaria'},{id:'shop',x:1396,y:1034,label:'Loja de Itens'},{id:'healer',x:1684,y:1034,label:'Curandeira'}];const near=targets.map(t=>({...t,d:Math.hypot(player.x-t.x,player.y-t.y)})).sort((a,b)=>a.d-b.d)[0];if(near&&near.d<100){interactBuilding(near.id);return;}const monster=monsters.filter(m=>m.alive).sort((a,b)=>Math.hypot(player.x-a.x,player.y-a.y)-Math.hypot(player.x-b.x,player.y-b.y))[0];if(monster&&Math.hypot(player.x-monster.x,player.y-monster.y)<68){showToast('Slime por perto. Use o botão de ataque para lutar.');return;}showToast('Aproxime-se de um NPC ou da porta de uma construção para interagir.');}
const monsters=slimeBaseSpawns.map((p,i)=>({id:i+1,x:p[0],y:p[1],homeX:p[0],homeY:p[1],hp:10,maxHp:10,atk:2,def:1,speed:92,alive:true,phase:i*1.8,attackCooldown:0,respawn:0,hitFlash:0}));
function attackNearestMonster(){
 if(screen!=='game')return;
 const inside=player.x>=2340&&player.x<=2610&&player.y>=780&&player.y<=1020;
 if(!inside){showToast('Entre no campo de caça para enfrentar os slimes.');return;}
 if((player.attackCooldown||0)>0)return;
 player.attackCooldown=.28;player.attackPulse=.24;
 const target=monsters.filter(m=>m.alive).map(m=>({m,d:Math.hypot(player.x-m.x,player.y-m.y)})).filter(v=>v.d<=62).sort((a,b)=>a.d-b.d)[0]?.m;
 if(!target){showToast('Chegue mais perto do slime para acertar o golpe.');return;}
 const damage=Math.max(1,attrValue('ATK')-target.def);target.hp=Math.max(0,target.hp-damage);target.hitFlash=.22;target.phase+=.7;target.knockX=(target.x-player.x)/Math.max(1,Math.hypot(target.x-player.x,target.y-player.y));target.knockY=(target.y-player.y)/Math.max(1,Math.hypot(target.x-player.x,target.y-player.y));target.knockTime=.10;
 if(target.hp===0){target.alive=false;target.respawn=8;target.windup=0;gainXP(5);player.gold+=2;player.gel=(player.gel||0)+1;const qs=questState();for(const qid of qs.accepted){if(!qs.completed.includes(qid)){const def=QUESTS.find(q=>q.id===qid);qs.progress[qid]=Math.min(def.need,(qs.progress[qid]||0)+1);if(qs.progress[qid]>=def.need){qs.completed.push(qid);qs.accepted=qs.accepted.filter(id=>id!==qid);player.gold+=(qid==='slime_intro'?15:30);gainXP(qid==='slime_intro'?30:60);showToast('Missão concluída: '+def.title+'! Recompensa recebida.');}}}saveQuestState(qs);try{const jobs=JSON.parse(localStorage.getItem('velkarys_jobs')||'{"accepted":[],"completed":[],"progress":{}}');if(jobs.accepted.includes('job_patrol'))jobs.progress.job_patrol=Math.min(2,(jobs.progress.job_patrol||0)+1);localStorage.setItem('velkarys_jobs',JSON.stringify(jobs));}catch(_){}saveGame(false);refreshMissionHud();showToast('Slime derrotado! +5 XP · +2 moedas.');}else{showToast(`Golpe certeiro! ${damage} de dano.`);}updateHud();
}
function updateMonsters(dt){
 const field={left:2345,right:2605,top:785,bottom:1015};
 const playerInside=player.x>=2340&&player.x<=2610&&player.y>=780&&player.y<=1020;
 player.attackCooldown=Math.max(0,(player.attackCooldown||0)-dt);
 player.invulnerable=Math.max(0,(player.invulnerable||0)-dt);
 for(const m of monsters){
  if(!m.alive){m.respawn-=dt;if(m.respawn<=0){m.alive=true;m.hp=m.maxHp;m.x=m.homeX;m.y=m.homeY;m.phase+=1.2;m.attackCooldown=.35;m.windup=0;m.knockTime=0;}continue;}
  m.phase+=dt;m.attackCooldown=Math.max(0,(m.attackCooldown||0)-dt);const previousWindup=m.windup||0;m.windup=Math.max(0,previousWindup-dt);
  const dx=player.x-m.x,dy=player.y-m.y,dist=Math.hypot(dx,dy);
  // A casa/campo de caça é a fronteira da IA: slimes não perseguem ninguém na vila.
  if(playerInside&&dist<220&&dist>47){const step=Math.min(64*dt,dist-47);m.x+=(dx/dist)*step;m.y+=(dy/dist)*step;}
  else if(!playerInside||dist>=220){m.x+=Math.sin(m.phase*.9)*m.speed*.12*dt;m.y+=Math.cos(m.phase*.7)*m.speed*.10*dt;const hx=m.x-m.homeX,hy=m.y-m.homeY,roam=Math.hypot(hx,hy);if(roam>24){m.x=m.homeX+hx/roam*24;m.y=m.homeY+hy/roam*24;}}
  if(m.knockTime>0){m.knockTime=Math.max(0,m.knockTime-dt);m.x+=(m.knockX||0)*34*dt;m.y+=(m.knockY||0)*34*dt;}
  m.x=Math.max(field.left,Math.min(field.right,m.x));m.y=Math.max(field.top,Math.min(field.bottom,m.y));
  const contact=Math.hypot(player.x-m.x,player.y-m.y);
  // Inicia um ataque anunciado; só acerta se o jogador continuar perto quando o golpe terminar.
  if(!playerInside){m.windup=0;continue;}
  if(previousWindup>0&&m.windup<=0){const finalDist=Math.hypot(player.x-m.x,player.y-m.y);if(finalDist<52&&(player.invulnerable||0)<=0){const damage=Math.max(1,m.atk-Math.floor(attrValue('DEF')*.15));player.hp=Math.max(0,(player.hp??attrValue('HP'))-damage);player.invulnerable=.62;player.hitFlash=.28;updateHud();if(player.hp<=0){player.hp=attrValue('HP');player.mp=attrValue('Mana');player.x=1540;player.y=900;clearMovement();player.invulnerable=1.2;saveGame(false);updateHud();showToast('Você foi derrotado e voltou à vila recuperado.');}else{showToast('Ataque do slime! -'+damage+' HP.');}}m.windup=0;}
  if(contact<51&&m.attackCooldown<=0&&m.windup<=0&&(player.invulnerable||0)<=0){m.windup=.32;m.attackCooldown=1.15;}
  if(m.hitFlash>0)m.hitFlash-=dt;
 }
}
